Ext._define('planning.hiring.commitmentnote.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'planning.hiring.commitmentnote.Window',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'reinforce', 'reversal', '-', 'search'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Status', dataIndex: 'icons', sortable: true, renderer: core.rendererIconGrid, width: 60},
                    {header: 'Número NE', dataIndex: 'numero_ne', sortable: true, width: 90},
                    {header: 'NE Principal', dataIndex: 'principal', sortable: true, width: 70},
                    {header: 'Valor (R$)', dataIndex: 'valor', sortable: true, renderer: toolkit.util.formatCurrency, width: 80},
                    {header: 'Saldo', dataIndex: 'saldo', sortable: true, renderer: this.formatCurrency, width: 80},
                    {header: 'Tipo', dataIndex: 'tipo_ne_display', sortable: true, width: 65},
                    {header: 'Contratado', dataIndex: 'fornecedor_display', id: 'autoExpandColumn', sortable: true},
                ]
            );

        return this._columnModel;
    },

    formatCurrency: function(value) {
        value = core.nullValue(value, 0);

        if (value === '-')
            return '<div style="text-align:right">-</div>';
        else
            return '<div style="text-align:right">' + Ext.util.Format.number(value, '0.0,00/i') + '</div>';
    },

    constructor: function(cfg) {
        cfg = (cfg ? cfg : {});

        Ext.applyIf(cfg, {
            columnAction: false,
        });

        planning.hiring.commitmentnote.Grid.superclass.constructor.call(this, cfg);
    },

    _solicitaReforco: function() {
        //Solicitando reforço
        this.janelaReforcoEstorno(100);
    },

    _solicitaEstorno: function() {
        //Solicitando estorno
        this.janelaReforcoEstorno(1);
    },

    janelaReforcoEstorno: function(action) {
        var sel = this.getSelectionModel().getSelected();
        if(sel){
            if (sel.get('ne_anterior') == null){
                Ext._create('planning.hiring.commitmentnote.Window', {
                    params: {
                    ne_anterior: sel.get('pk'),
                    reforco_estorno: action,
                    contrato: this.params.contrato,
                    },
                    action: 'create',
                    callback: {
                    success: {
                        scope: this,
                        fn: function(args) {
                            this.getStore().reload();
                        }
                    }
                    },
                }).show();
            } else {
                Ext.Msg.show({
                    'title': 'Nota de Empenho',
                    'msg': 'Não posso solicitar reforço ou estorno para esta NE.',
                    'icon': Ext.Msg.WARNING,
                    'buttons': Ext.Msg.OK
                });
            }
        } else {
            Ext.Msg.show({
                'title': 'Nota de Empenho',
                'msg': 'Primeiro selecione a NE.',
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK
            });
        }
    },

    getReinforceAction: function() {
        if(!this._reinforceAction)
            this._reinforceAction = Ext._create('Ext.Button', {
                text: 'Solicitar Reforço',
                iconCls: 'icon-agree icon-agree-add',
                scope: this,
                handler: this._solicitaReforco
            });

        return this._reinforceAction;
    },

    getReversalAction: function() {
        if(!this._reinforcementAction)
            this._reinforcementAction = Ext._create('Ext.Button', {
                text: 'Solicitar Estorno',
                iconCls: 'icon-agree icon-agree-list-remove',
                scope: this,
                handler: this._solicitaEstorno
            });

        return this._reinforcementAction;
    },

    getSendAction: function() {
        if(!this._sendAction)
            this._sendAction = Ext._create('Ext.Button', {
                text: 'Enviar para o fornecedor',
                iconCls: 'icon-agree icon-agree-document-send',
                scope: this,
//                handler: this._solicitaProrrogacao
            });

        return this._sendAction;
    },
});

core.RestfulGrid.register(
    'planning.hiring.commitmentnote.Restful',
    'planning.hiring.commitmentnote.Grid'
);
